import os
from pathlib import Path

import pytest

NOTES_DIR = "notes"


def first_readable(names: list[str]) -> str:
    """Return the text of the first readable file in `names` under `notes`.

    Each name is looked up inside the directory `notes` (relative to the
    current working directory). Names are untrusted: any name that would
    resolve to a location outside `notes` (via `..`, an absolute path, a
    symlink pointing outside, etc.) is skipped, never read. Names that are
    empty, contain NUL bytes, are too long, refer to missing files or
    directories, or refer to files that cannot be read or decoded as UTF-8
    are also skipped. Names in subdirectories of `notes` are allowed.
    Returns "" when `names` is empty or no name yields a readable file.
    Never raises because of a bad name or an unreadable file.
    """
    try:
        root = Path(NOTES_DIR).resolve()
    except (OSError, RuntimeError, ValueError):
        return ""
    for name in names:
        if not name or "\x00" in name:
            continue
        try:
            candidate = (root / name).resolve()
            if candidate == root or not candidate.is_relative_to(root):
                continue
            if not candidate.is_file():
                continue
            return candidate.read_text(encoding="utf-8")
        except (OSError, RuntimeError, ValueError):
            # ValueError covers UnicodeDecodeError and embedded-NUL errors;
            # RuntimeError covers symlink loops on older interpreters.
            continue
    return ""


@pytest.fixture
def sandbox(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> Path:
    notes = tmp_path / NOTES_DIR
    notes.mkdir()
    (tmp_path / "secret.txt").write_text("SECRET")
    monkeypatch.chdir(tmp_path)
    return tmp_path


def test_empty_list(sandbox: Path) -> None:
    assert first_readable([]) == ""


def test_returns_first_readable_skipping_missing(sandbox: Path) -> None:
    (sandbox / "notes" / "a.txt").write_text("alpha")
    (sandbox / "notes" / "b.txt").write_text("beta")
    assert first_readable(["missing.txt", "a.txt", "b.txt"]) == "alpha"


def test_none_readable(sandbox: Path) -> None:
    assert first_readable(["x.txt", "y.txt"]) == ""


def test_missing_notes_dir(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> None:
    monkeypatch.chdir(tmp_path)
    assert first_readable(["a.txt"]) == ""


def test_subdirectory_file_allowed(sandbox: Path) -> None:
    sub = sandbox / "notes" / "sub"
    sub.mkdir()
    (sub / "c.txt").write_text("gamma")
    assert first_readable(["sub/c.txt"]) == "gamma"


def test_dotdot_traversal_rejected(sandbox: Path) -> None:
    assert first_readable(["../secret.txt"]) == ""
    (sandbox / "notes" / "ok.txt").write_text("ok")
    assert first_readable(["../secret.txt", "ok.txt"]) == "ok"


def test_nested_dotdot_traversal_rejected(sandbox: Path) -> None:
    (sandbox / "notes" / "sub").mkdir()
    assert first_readable(["sub/../../secret.txt"]) == ""


def test_absolute_path_outside_rejected(sandbox: Path) -> None:
    secret = str(sandbox / "secret.txt")
    assert first_readable([secret]) == ""


def test_sibling_directory_with_same_prefix_rejected(sandbox: Path) -> None:
    evil = sandbox / "notes_evil"
    evil.mkdir()
    (evil / "x.txt").write_text("EVIL")
    assert first_readable(["../notes_evil/x.txt"]) == ""


def test_symlink_to_outside_file_rejected(sandbox: Path) -> None:
    link = sandbox / "notes" / "link.txt"
    try:
        link.symlink_to(sandbox / "secret.txt")
    except (OSError, NotImplementedError):
        pytest.skip("symlinks unavailable")
    assert first_readable(["link.txt"]) == ""


def test_symlink_to_outside_dir_rejected(sandbox: Path) -> None:
    link = sandbox / "notes" / "dirlink"
    try:
        link.symlink_to(sandbox, target_is_directory=True)
    except (OSError, NotImplementedError):
        pytest.skip("symlinks unavailable")
    assert first_readable(["dirlink/secret.txt"]) == ""


def test_symlink_inside_notes_allowed(sandbox: Path) -> None:
    (sandbox / "notes" / "real.txt").write_text("real")
    link = sandbox / "notes" / "alias.txt"
    try:
        link.symlink_to(sandbox / "notes" / "real.txt")
    except (OSError, NotImplementedError):
        pytest.skip("symlinks unavailable")
    assert first_readable(["alias.txt"]) == "real"


def test_directory_name_skipped(sandbox: Path) -> None:
    (sandbox / "notes" / "adir").mkdir()
    (sandbox / "notes" / "f.txt").write_text("file")
    assert first_readable(["adir", "f.txt"]) == "file"


def test_empty_and_dot_names_skipped(sandbox: Path) -> None:
    (sandbox / "notes" / "f.txt").write_text("file")
    assert first_readable(["", ".", "f.txt"]) == "file"
    assert first_readable(["", "."]) == ""


def test_nul_byte_name_skipped(sandbox: Path) -> None:
    (sandbox / "notes" / "f.txt").write_text("file")
    assert first_readable(["a\x00b", "f.txt"]) == "file"


def test_very_long_name_skipped(sandbox: Path) -> None:
    (sandbox / "notes" / "f.txt").write_text("file")
    assert first_readable(["a" * 10000, "f.txt"]) == "file"


def test_undecodable_file_skipped(sandbox: Path) -> None:
    (sandbox / "notes" / "bin.dat").write_bytes(b"\xff\xfe\xfa")
    (sandbox / "notes" / "f.txt").write_text("file")
    assert first_readable(["bin.dat", "f.txt"]) == "file"


@pytest.mark.skipif(
    hasattr(os, "geteuid") and os.geteuid() == 0,
    reason="root can read any file",
)
def test_unreadable_file_skipped(sandbox: Path) -> None:
    locked = sandbox / "notes" / "locked.txt"
    locked.write_text("locked")
    locked.chmod(0)
    (sandbox / "notes" / "f.txt").write_text("file")
    try:
        assert first_readable(["locked.txt", "f.txt"]) == "file"
        assert first_readable(["locked.txt"]) == ""
    finally:
        locked.chmod(0o600)


def test_empty_file_returns_empty_string_and_is_first(sandbox: Path) -> None:
    (sandbox / "notes" / "empty.txt").write_text("")
    (sandbox / "notes" / "f.txt").write_text("file")
    assert first_readable(["empty.txt", "f.txt"]) == ""
